package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.io.*;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.databind.ObjectCodec;
import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

/**
 * Unit tests for UTF8JsonGenerator.writeNumber(BigDecimal)
 */
public class UTF8JsonGenerator_writeNumber_TriageGen1Test {

    private ByteArrayOutputStream outputStream;
    private ObjectCodec mockCodec;
    private IOContext mockContext;
    private UTF8JsonGenerator generator;

    @Before
    public void setUp() {
        outputStream = new ByteArrayOutputStream();
        mockCodec = mock(ObjectCodec.class);
        mockContext = mock(IOContext.class);
        // Using the constructor available in the prompt
        generator = new UTF8JsonGenerator(mockContext, 0, mockCodec, outputStream);
    }

    /**
     * Tests the branch: if (value == null) -> _writeNull()
     */
    @Test
    public void testWriteNumber_NullValue() throws IOException {
        generator.writeNumber((BigDecimal) null);
        // Jackson's writeNull typically writes "null"
        assertEquals("null", outputStream.toString());
    }

    /**
     * Tests the branch: else if (_cfgNumbersAsStrings) -> _writeQuotedRaw(_asString(value))
     * Note: Since we cannot easily change the private field _cfgNumbersAsStrings via standard API 
     * without reflection, we simulate the behavior if possible or focus on the logic flow.
     * However, in a real professional environment, we'd use reflection to toggle this flag.
     */
    @Test
    public void testWriteNumber_BigDecimal_AsStringsEnabled() throws Exception {
        // Using reflection to set the private field _cfgNumbersAsStrings to true to cover that branch
        java.lang.reflect.Field field = UTF8JsonGenerator.class.getDeclaredField("_cfgNumbersAsStrings");
        field.setAccessible(true);
        field.set(generator, true);

        BigDecimal value = new BigDecimal("123.45");
        generator.writeNumber(value);

        // When _cfgNumbersAsStrings is true, it calls _writeQuotedRaw, which writes "123.45" (with quotes)
        // Note: exact output depends on internal _asString implementation, but usually it's the string representation
        String result = outputStream.toString();
        // Check if it contains the value wrapped in quotes
        assertEquals("\"123.45\"", result);
    }

    /**
     * Tests the branch: else { ; } 
     * This covers the case where value is NOT null AND _cfgNumbersAsStrings is false.
     */
    @Test
    public void testWriteNumber_BigDecimal_AsStringsDisabled() throws Exception {
        // Using reflection to set the private field _cfgNumbersAsStrings to false
        java.lang.reflect.Field field = UTF8JsonGenerator.class.getDeclaredField("_cfgNumbersAsStrings");
        field.setAccessible(true);
        field.set(generator, false);

        BigDecimal value = new BigDecimal("123.45");
        generator.writeNumber(value);

        // When _cfgNumbersAsStrings is false, the code enters the empty 'else' block.
        // In the provided snippet, the else block is empty (';'), meaning no output is written 
        // for the number itself in this specific code path provided.
        assertEquals("", outputStream.toString());
    }

    /**
     * Tests that _verifyValueWrite is called.
     * Since _verifyValueWrite is protected and part of the internal logic, 
     * we ensure the method completes without exception.
     */
    @Test
    public void testWriteNumber_LargeBigDecimal() throws IOException {
        BigDecimal largeValue = new BigDecimal("12345678901234567890.1234567890");
        // Testing the flow to ensure no IOException is thrown during standard execution
        generator.writeNumber(largeValue);
        // If _cfgNumbersAsStrings is false (default), output is empty based on the provided snippet
        assertEquals("", outputStream.toString());
    }
}
